def transform(g):
    g=[row[:] for row in g]
    h,w=len(g),len(g[0])
    rows3=[r for r in range(h) if sum(g[r][c]==3 for c in range(w))>w//2]
    cols3=[c for c in range(w) if sum(g[r][c]==3 for r in range(h))>h//2]
    r0,r1,c0,c1=min(rows3),max(rows3),min(cols3),max(cols3)
    interior=[(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)]
    seeds=[(r,c) for r,c in interior if g[r][c]==3]
    if not seeds:
        for r,c in interior:
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                if g[r+dr][c+dc]==3 and (r+dr,c+dc) not in interior: seeds.append((r,c))
    s=seeds[0]
    for r,c in interior:
        if g[r][c]==3: continue
        d=max(abs(r-s[0]),abs(c-s[1]))
        g[r][c]= 2 if d%2==0 and d>0 else 4
    return g
